// src/v1/index.ts
import { createREST } from "@abacatepay/rest";
import {
  Routes
} from "@abacatepay/types/v1";
var hasWarnedAboutV1 = false;
var AbacatePay = ({ secret, rest }) => {
  if (!hasWarnedAboutV1) {
    hasWarnedAboutV1 = true;
    console.warn("[@abacatepay/sdk] v1 is deprecated, migrate to the default v2 export (`@abacatepay/sdk`) — see https://docs.abacatepay.com");
  }
  const client = createREST({
    secret,
    ...rest,
    version: 1
  });
  return {
    rest: client,
    customers: {
      create(body) {
        return client.post(Routes.customer.create, {
          body
        });
      },
      list() {
        return client.get(Routes.customer.list);
      }
    },
    billings: {
      create(body) {
        return client.post(Routes.billing.create, {
          body
        });
      },
      list() {
        return client.get(Routes.billing.list);
      }
    },
    pix: {
      create(body) {
        return client.post(Routes.pix.createQRCode, {
          body
        });
      },
      simulate(id, metadata) {
        return client.post(Routes.pix.simulatePayment({ id }), {
          body: { metadata }
        });
      },
      status(id) {
        return client.get(Routes.pix.checkStatus({ id }));
      }
    },
    coupons: {
      create(body) {
        return client.post(Routes.coupon.create, {
          body
        });
      },
      list() {
        return client.get(Routes.coupon.list);
      }
    },
    withdraw: {
      create(body) {
        return client.post(Routes.withdraw.create, { body });
      },
      list() {
        return client.get(Routes.withdraw.list);
      },
      get(id) {
        return client.get(Routes.withdraw.get({ externalId: id }));
      }
    },
    store: {
      get() {
        return client.get(Routes.store.get);
      }
    },
    mrr: {
      get() {
        return client.get(Routes.mrr.get);
      },
      renevue(start, end) {
        return client.get(`${Routes.mrr.revenue}?startDate=${start}&endDate=${end}`);
      },
      merchant() {
        return client.get(Routes.mrr.merchant);
      }
    }
  };
};
export {
  AbacatePay
};
